// Served only by the authenticated local SDK companion, never a general HTTP proxy.
const allowed=new Set(['https://wirevo-furka.equalwood4.chatgpt.site','http://127.0.0.1:4173','http://localhost:4173']);
const nonce=location.hash.slice(1),parent=window.opener,status=document.getElementById('status');history.replaceState(null,'',location.pathname);let peerOrigin='',token='',paired=false;
function send(message){if(parent&&peerOrigin)parent.postMessage({...message,nonce},peerOrigin);}
const validPath=(p,m)=>m==='GET'&&(p==='/v1/status'||/^\/v1\/jobs\/[0-9a-f-]{36}\?cursor=\d+$/.test(p))||m==='POST'&&(p==='/v1/jobs'||/^\/v1\/jobs\/[0-9a-f-]{36}\/cancel$/.test(p));
async function request(path,method='GET',body){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),25000);try{const r=await fetch(path,{method,credentials:'omit',cache:'no-store',signal:controller.signal,headers:{Authorization:'Bearer '+token,...(body===undefined?{}:{'Content-Type':'application/json'})},...(body===undefined?{}:{body:JSON.stringify(body)})});const data=await r.json();if(!r.ok)throw Error(data.error||'SDK HTTP '+r.status);return data;}finally{clearTimeout(timer);}}
window.addEventListener('message',async event=>{const m=event.data;if(event.source!==parent||!allowed.has(event.origin)||m?.nonce!==nonce)return;
 if(m.type==='wirevo-sdk-pair'&&!paired){if(typeof m.token!=='string'||!/^[A-Za-z0-9_-]{32,100}$/.test(m.token))return;peerOrigin=event.origin;token=m.token;try{const result=await request('/v1/status');paired=true;status.textContent='Bağlı. Wirevo’ya dönüp Derle ve ardından Çalıştır düğmesine basabilirsiniz.';send({type:'wirevo-sdk-paired',status:result});}catch(e){token='';status.textContent=e.message;send({type:'wirevo-sdk-paired',error:e.message});}return;}
 if(m.type!=='wirevo-sdk-request'||!paired||event.origin!==peerOrigin||typeof m.id!=='string'||!validPath(m.path,m.method))return;
 try{if(JSON.stringify(m.body??{}).length>512000)throw Error('SDK kaynak boyutu aşıldı.');const data=await request(m.path,m.method,m.body);send({type:'wirevo-sdk-response',id:m.id,data});}catch(e){send({type:'wirevo-sdk-response',id:m.id,error:e.name==='AbortError'?'SDK penceresi yanıt beklerken zaman aşımına uğradı.':e.message});}
});
if(!parent||!/^[0-9a-f-]{36}$/.test(nonce))status.textContent='Bu pencereyi Wirevo → Pico SDK / CMake → Yerel pencereyle bağlan düğmesinden açın.';else for(const origin of allowed)parent.postMessage({type:'wirevo-sdk-ready',nonce},origin);
